# Proposed response-only artifact

The fixture does not provide the source repository alias/revision/path/line/function, production HTTP handler constructor, exact idempotency header name, command-ID JSON field name, or error-code JSON field name. Those unavailable identities are explicit below; they must be replaced from repository evidence before this can be accepted as a completed port.

## Proposed file

`tests/contract/http/create_order_idempotency_test.go`

```go
package httpcontract_test

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

// Ported from:
//   repository: <UNAVAILABLE_SOURCE_REPOSITORY>@<UNAVAILABLE_SOURCE_REVISION>
//   source: <UNAVAILABLE_SOURCE_PATH>:<UNAVAILABLE_SOURCE_LINE>
//   test: <UNAVAILABLE_SOURCE_TEST_FUNCTION>
// Adaptations:
//   - The source HTTP client is replaced by httptest requests against the
//     production Go HTTP handler.
// Assertions preserved:
//   - The initial request returns HTTP 201.
//   - Quantity is returned exactly as the string "0.0100".
//   - stopLoss is present in the response and is JSON null.
//   - The command ID is "cmd-7".
//   - A same-key, same-request retry returns byte-equivalent status and body.
//   - A same-key, different-quantity request returns HTTP 409 with code
//     IDEMPOTENCY_KEY_REUSED.
func TestCreateOrder_IdempotencyReplayAndKeyReuse(t *testing.T) {
	binding := repositoryOrdersContractBinding(t)

	first := postOrder(
		t,
		binding.handler,
		binding.idempotencyHeader,
		"same-key",
		"0.0100",
	)
	if first.status != http.StatusCreated {
		t.Fatalf("first request status = %d, want %d; body=%s",
			first.status, http.StatusCreated, first.body)
	}

	firstJSON := decodeJSONObject(t, first.body)
	requireJSONStringField(t, firstJSON, "quantity", "0.0100")
	requireJSONNullField(t, firstJSON, "stopLoss")
	requireJSONStringField(t, firstJSON, binding.commandIDField, "cmd-7")

	retry := postOrder(
		t,
		binding.handler,
		binding.idempotencyHeader,
		"same-key",
		"0.0100",
	)
	if retry.status != first.status {
		t.Fatalf("retry status = %d, want byte-equivalent status %d",
			retry.status, first.status)
	}
	if !bytes.Equal(retry.body, first.body) {
		t.Fatalf(
			"retry body is not byte-equivalent:\nfirst: %q\nretry: %q",
			first.body,
			retry.body,
		)
	}

	conflict := postOrder(
		t,
		binding.handler,
		binding.idempotencyHeader,
		"same-key",
		"0.0200",
	)
	if conflict.status != http.StatusConflict {
		t.Fatalf("key-reuse status = %d, want %d; body=%s",
			conflict.status, http.StatusConflict, conflict.body)
	}

	conflictJSON := decodeJSONObject(t, conflict.body)
	requireJSONStringField(
		t,
		conflictJSON,
		binding.errorCodeField,
		"IDEMPOTENCY_KEY_REUSED",
	)
}

type ordersContractBinding struct {
	handler           http.Handler
	idempotencyHeader string
	commandIDField    string
	errorCodeField    string
}

// repositoryOrdersContractBinding is the only repository-specific adapter
// required by this contract test.
//
// Replace this placeholder with the real production handler construction and
// exact frozen contract field/header identities. Do not implement the asserted
// behavior in a test fake.
func repositoryOrdersContractBinding(t *testing.T) ordersContractBinding {
	t.Helper()
	t.Fatal(
		"repository binding unavailable in the supplied fixture: " +
			"production handler constructor, idempotency header, " +
			"command-ID field, and error-code field are required",
	)
	return ordersContractBinding{}
}

type recordedResponse struct {
	status int
	body   []byte
}

func postOrder(
	t *testing.T,
	handler http.Handler,
	idempotencyHeader string,
	idempotencyKey string,
	quantity string,
) recordedResponse {
	t.Helper()

	// stopLoss is deliberately omitted.
	body := []byte(`{"quantity":` + mustJSONString(t, quantity) + `}`)

	req := httptest.NewRequest(http.MethodPost, "/v1/orders", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set(idempotencyHeader, idempotencyKey)

	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, req)

	return recordedResponse{
		status: recorder.Code,
		body:   bytes.Clone(recorder.Body.Bytes()),
	}
}

func mustJSONString(t *testing.T, value string) string {
	t.Helper()

	encoded, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("encode JSON string: %v", err)
	}
	return string(encoded)
}

func decodeJSONObject(t *testing.T, body []byte) map[string]json.RawMessage {
	t.Helper()

	var object map[string]json.RawMessage
	if err := json.Unmarshal(body, &object); err != nil {
		t.Fatalf("decode response object %q: %v", body, err)
	}
	if object == nil {
		t.Fatalf("response is not a JSON object: %q", body)
	}
	return object
}

func requireJSONStringField(
	t *testing.T,
	object map[string]json.RawMessage,
	field string,
	want string,
) {
	t.Helper()

	raw, exists := object[field]
	if !exists {
		t.Fatalf("response field %q is absent", field)
	}

	var got string
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatalf("response field %q is not a JSON string: %s", field, raw)
	}
	if got != want {
		t.Fatalf("response field %q = %q, want %q", field, got, want)
	}
}

func requireJSONNullField(
	t *testing.T,
	object map[string]json.RawMessage,
	field string,
) {
	t.Helper()

	raw, exists := object[field]
	if !exists {
		t.Fatalf("response field %q is absent; want explicit null", field)
	}
	if !bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		t.Fatalf("response field %q = %s, want null", field, raw)
	}
}
